#!/bin/sh
# Generate a local .env with random secrets. Never overwrites an existing .env.
set -eu
if [ -f .env ]; then echo ".env exists; leaving it unchanged"; exit 0; fi
rand() { python3 -c 'import secrets; print(secrets.token_urlsafe(24))'; }
umask 077
cat > .env <<EOF
# Local development secrets. Generated by scripts/make-env.sh. Git-ignored.
POSTGRES_USER=fleetforge
POSTGRES_PASSWORD=$(rand)
FLEETFORGE_APP_DB_PASSWORD=$(rand)
FLEETFORGE_PROJECTOR_DB_PASSWORD=$(rand)
FLEETFORGE_MISSION_CONSUMER_DB_PASSWORD=$(rand)
FLEETFORGE_CDC_DB_PASSWORD=$(rand)
FLEETFORGE_READONLY_DB_PASSWORD=$(rand)
GRAFANA_ADMIN_PASSWORD=$(rand)
EOF
echo "wrote .env (mode 600)"
